import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.99, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function post(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const res = await fetch(`http://localhost:${server.address().port}/orders`, {
      method: 'POST', body: JSON.stringify({ items }),
    })
    return { status: res.status, body: await res.json() }
  } finally { server.close() }
}

const totalOf = async (items) => (await post(items)).body.total

// Characterization tests: pin current behavior (10% off when subtotal > 100, result floored).
test('no discount below threshold', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 5 }]), 50)
})

test('no discount at exactly 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
})

test('discount applies just over 100 (100.5 -> 90.45 -> 90)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }, { sku: 'C', qty: 0.5 }]), 90)
})

test('discount on larger order (200 -> 180)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 20 }]), 180)
})

test('discount on large order, multiple skus (1000 + 51 = 1051 -> 945.9 -> 945)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 100 }, { sku: 'B', qty: 2 }]), 945)
})

test('total is floored, not rounded (3 x 33.33 = 99.99 -> 99)', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 99)
})

test('floor drops cents after discount (4 x 33.33 = 133.32 -> 119.988 -> 119)', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 119)
})

test('empty items rejected', async () => {
  assert.equal((await post([])).status, 400)
})
EOF
